SELECT * 
FROM accommodation
WHERE 1=1

    AND acm_name LIKE CONCAT('%', #{keyword}, '%')


    AND check_in >= #{startDate}


    AND check_out <= #{finishDate}


    AND max_person >= #{numberPeople}

SELECT acm_type_id, acm_type
FROM accommodation_type
WHERE acm_type_id = #{acm_type_id}
